{
  "hypotheses": [
    {
      "stance": "bull",
      "mechanism": "若 UPS 隨最大客戶減量同步整併美國配送路線，相較於減量後仍維持原網路，可減少低載運量班次的營運支出。若當年節省足以抵銷轉型成本，便可支撐合併營業利益率。約 10 億美元是多年節省目標，2025 年可實現的淨額未知。",
      "target": "UPS",
      "horizon": "2026-03-31",
      "catalyst": "UPS 於 2025 年 1 月 30 日宣布重整美國網路。觀察其後季度業績公告是否披露已完成的整併或已實現的節省，再以全年業績檢驗獲利結果。",
      "prediction": "截至 2026-03-31，UPS 全年業績公告顯示，2025 年合併營業利益率按指引相同口徑達 10.8% 或以上。以指引中心值作為情境門檻；該指標是獲利代理，無法單獨歸因於美國網路重整。",
      "invalidation": "截至 2026-03-31，UPS 公布的 2025 年同口徑合併營業利益率低於 10.8%，即推翻此獲利預測。個別路線仍可能已產生節省。",
      "claim_ids": ["fact:ups-q4:network", "fact:ups-q4:volume", "fact:ups-q4:guidance"]
    },
    {
      "stance": "bear",
      "mechanism": "若最大客戶於 2025 年實際交運的包裹較維持原安排時減少，UPS 可完成配送並認列收入的件數也會減少。若減量快於編製指引時的假設，且其他客戶新增收入不足以填補缺口，全年合併營收可能低於指引中心值。客戶減量時程、每件收入及指引內含的減量幅度均未披露。",
      "target": "UPS",
      "horizon": "2026-03-31",
      "catalyst": "2025 年 1 月 30 日公布的是原則協議。觀察 UPS 隨後在 2025 年季度業績中是否確認實際減量，以及是否因此調降全年營收展望。逾 50% 的減量目標落在研究期後的 2026 年下半年。",
      "prediction": "截至 2026-03-31，UPS 全年業績公告顯示，2025 年合併營收低於原指引中心值 890 億美元。合併營收是代理指標，須有 UPS 對減量影響的說明，才能將落差連結至該客戶。",
      "invalidation": "截至 2026-03-31，UPS 公布的 2025 年合併營收達 890 億美元或以上，即推翻此營收預測。其他業務可能已抵銷客戶減量。",
      "claim_ids": ["fact:ups-q4:volume", "fact:ups-q4:guidance"]
    }
  ],
  "assessment": {
    "thesis": "UPS 在最大客戶逐步減量期間，能否守住 2025 年營業利益率，取決於美國網路能否及時撤除閒置運能，以及當年淨節省能否抵銷流失包裹的獲利貢獻。",
    "key_gap": "最大疑問是減量與節省的時間差。若 UPS 未量化兩者，精確歸因需非公開的客戶實際配送量、每件貢獻及路線重整成本紀錄。",
    "next_check": "在 2025 年各季業績公告中核對 UPS 是否首次量化已實現節省及實際減量，再於 2026-03-31 前查閱其 2025 年第四季暨全年業績，比對全年合併營收與同口徑營業利益率。前一年度同類公告發布於 2025-01-30。",
    "evidence_limits": [
      {
        "evidence_id": "ups-q4:guidance",
        "limit": "提供 2025 年合併營收約 890 億美元及營業利益率約 10.8% 的前瞻基準。兩者均為概估，未拆出客戶減量或網路節省的假設。"
      },
      {
        "evidence_id": "ups-q4:network",
        "limit": "證實 UPS 已宣布重整美國網路，約 10 億美元屬多年流程重設目標。公告未提供 2025 年已實現金額或扣除轉型成本後的淨效益。"
      },
      {
        "evidence_id": "ups-q4:volume",
        "limit": "最大客戶減量屬原則協議，未揭露 2025 年實際減量或收入影響。SurePost 自 2025-01-01 起全數改由 UPS 自行配送則為已發生的營運變動，也會影響網路負荷。"
      }
    ],
    "public_checks": [
      {
        "metric": "美國網路已完成的整併及已實現的節省金額",
        "source_to_watch": "UPS 投資人關係網站的季度業績公告及業績說明會",
        "window": "從 2025 年第一季至第四季業績揭露，最遲檢視至 2026-03-31。",
        "impact_on_thesis": "已完成整併可支持降本機制開始運作。若另披露當期節省及轉型成本，才可估算對利益率的影響。僅重申多年目標則效益仍待驗證。",
        "evidence_ids": ["ups-q4:network"]
      },
      {
        "metric": "2025 年全年合併營收指引相對原估 890 億美元的修訂方向及理由",
        "source_to_watch": "UPS 季度業績公告的全年展望及管理層說明",
        "window": "從 2025 年第一季業績至全年結算前的展望更新，再於 2026-03-31 前核對全年實績。",
        "impact_on_thesis": "若 UPS 因最大客戶已實際減量而下修營收，則提高減量拖累營收的可信度。若公司確認其他收入已填補缺口，則降低信心。單看合併指引修訂無法辨識客戶貢獻。",
        "evidence_ids": ["ups-q4:guidance", "ups-q4:volume"]
      }
    ],
    "supply_chain": [],
    "trade_opportunities": []
  }
}
